// Replace this Code node with an HTTP Request to your actual API.
// This simulation flips status to 'done' after 3 checks.

const item = $input.first().json;
const counter = (item.counter || 0) + 1;
const status = counter >= 3 ? 'done' : 'pending';

return [{
  json: {
    counter,
    status,
    message: status === 'done'
      ? 'Job completed successfully!'
      : `Still processing... (check ${counter} of 3)`
  }
}];
